import{_ as t,o as s,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Morning Lightning Talks | Ceph Days London 2024","description":"","frontmatter":{"title":"Morning Lightning Talks | Ceph Days London 2024","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Performance Optimization","Storage Cluster","Crimson"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Morning_Lightning_Talks_Ceph_Days_London_2024.md","filePath":"posts/2024/Morning_Lightning_Talks_Ceph_Days_London_2024.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Morning_Lightning_Talks_Ceph_Days_London_2024.md"};function i(g,n,l,a,p,C){return s(),o("div",null,[...n[0]||(n[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年（具体日期未提及）</p><p><strong>参会人员</strong>： Dave Holland（Sanger Institute系统管理员），Jose Palas Perez（IBM SE团队），Ceph社区成员</p><p><strong>会议主题</strong>： Sanger Institute的Ceph存储使用经验分享，Crimson性能测试及优化</p><p><strong>会议内容</strong>：</p><p><strong>一、Sanger Institute的Ceph存储使用经验</strong></p><ul><li><strong>Sanger Institute简介</strong>： Sanger Institute是英国人类基因组计划的贡献者，专注于基因组研究和测序。</li><li><strong>Ceph存储应用</strong>： Sanger Institute使用Ceph存储进行数据存储，包括OpenStack私有云存储、S3对象存储和数据传输。</li><li><strong>Ceph存储优势</strong>： Ceph存储具有高可靠性、可扩展性和性能优势。</li><li><strong>Ceph存储挑战</strong>： 在使用过程中遇到了OSD崩溃、性能瓶颈和监控不足等问题。</li></ul><p><strong>二、Ceph存储优化方案</strong></p><ul><li><strong>解决OSD崩溃</strong>： 通过将垃圾回收池迁移到NVMe存储来解决OSD崩溃问题。</li><li><strong>性能优化</strong>： 通过调整Ceph配置和优化工作负载来提高Ceph存储性能。</li><li><strong>监控和可观测性</strong>： 实施新的监控系统以更好地监控Ceph存储性能。</li></ul><p><strong>三、Crimson性能测试及优化</strong></p><ul><li><strong>Crimson介绍</strong>： Crimson是Ceph的新一代OSD，具有更高的性能和可扩展性。</li><li><strong>Crimson性能测试</strong>： Jose Palas Perez对Crimson进行了性能测试，主要关注CPU利用率。</li><li><strong>测试结果</strong>： 测试结果表明，Crimson能够充分利用CPU资源，并具有良好的性能。</li><li><strong>Crimson优化</strong>： 计划进一步优化Crimson的性能，例如调整CPU核心分配和优化Ceph配置。</li></ul><p><strong>四、会议总结</strong></p><ul><li>Sanger Institute的Ceph存储使用经验为Ceph社区提供了宝贵的参考。</li><li>Crimson性能测试结果表明，Crimson具有很高的性能潜力。</li><li>Ceph社区需要共同努力，优化Ceph存储性能和可观测性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sanger Institute将继续优化Ceph存储性能和可观测性。</li><li>Ceph社区将共同推进Crimson的性能优化和功能完善。</li><li>Ceph社区将加强监控和可观测性工具的开发。</li></ul>',15)])])}const u=t(r,[["render",i]]);export{h as __pageData,u as default};
